from flask import Flask, request

app = Flask(__name__)

@app.get("/search")
def search():
    q = request.args.get("q", "")
    page = request.args.get("page", 1, type=int)
    tags = request.args.getlist("tag")
    return {"q": q, "page": page, "tags": tags}

@app.post("/notes")
def add_note():
    data = request.get_json()
    return {"saved": data["text"], "agent": request.headers.get("User-Agent")}

c = app.test_client()
print(c.get("/search?q=flask&page=x&tag=a&tag=b").json)
# {'page': 1, 'q': 'flask', 'tags': ['a', 'b']}
print(c.post("/notes", json={"text": "hi"}).json["saved"])   # hi
print(c.post("/notes", data="hi").status_code)              # 415

from flask import Flask, make_response

app = Flask(__name__)
USERS = {1: "ann"}

@app.get("/users/<int:uid>")
def get_user(uid):
    if uid not in USERS:
        return {"error": "user not found"}, 404
    return {"id": uid, "name": USERS[uid]}

@app.get("/greet")
def greet():
    resp = make_response("hello")
    resp.headers["X-Hello"] = "world"
    resp.set_cookie("seen", "1", httponly=True)
    return resp

c = app.test_client()
r = c.get("/users/2"); print(r.status_code, r.json, r.content_type)
# 404 {'error': 'user not found'} application/json
r = c.get("/greet"); print(r.headers["X-Hello"], r.headers["Set-Cookie"])
# world seen=1; HttpOnly; Path=/

from flask import Flask, redirect, url_for

app = Flask(__name__)

@app.get("/posts/<int:post_id>")
def show_post(post_id):
    return f"post {post_id}"

@app.get("/latest")
def latest():
    return redirect(url_for("show_post", post_id=7))

with app.test_request_context():
    print(url_for("show_post", post_id=3))                 # /posts/3
    print(url_for("show_post", post_id=3, ref="mail"))     # /posts/3?ref=mail
    print(url_for("show_post", post_id=3, _external=True)) # http://localhost/posts/3
    print(url_for("static", filename="css/site.css"))      # /static/css/site.css

print(app.test_client().get("/latest").headers["Location"])   # /posts/7

from flask import Flask, abort
from werkzeug.exceptions import HTTPException

app = Flask(__name__)
BOOKS = {1: "Dune"}

@app.get("/books/<int:bid>")
def book(bid):
    if bid not in BOOKS:
        abort(404, description=f"no book {bid}")
    return {"title": BOOKS[bid]}

@app.get("/boom")
def boom():
    return 1 / 0

@app.errorhandler(HTTPException)
def http_error(e):
    return {"error": e.name, "detail": e.description}, e.code
@app.errorhandler(ZeroDivisionError)
def math_error(e):
    return {"error": "calculation failed"}, 500
c = app.test_client()
print(c.get("/books/9").json)        # {'detail': 'no book 9', 'error': 'Not Found'}
print(c.get("/boom").status_code)    # 500

from flask import Flask, session

app = Flask(__name__)
app.config.update(SECRET_KEY="change-me", SESSION_COOKIE_SAMESITE="Lax")

@app.post("/cart/<item>")
def add(item):
    cart = session.setdefault("cart", [])
    cart.append(item)
    session.modified = True         # in-place change: tell Flask to save it
    return {"cart": cart}

@app.post("/logout")
def logout():
    session.clear()
    return {"ok": True}

c = app.test_client()
c.post("/cart/apple")
print(c.post("/cart/pear").json)             # {'cart': ['apple', 'pear']}
with c.session_transaction() as s:           # peek at the stored session
    print(s["cart"])                          # ['apple', 'pear']
c.post("/logout")
print(c.post("/cart/fig").json)              # {'cart': ['fig']}

from flask import Flask, flash, get_flashed_messages, redirect, request, url_for

app = Flask(__name__)
app.secret_key = "dev-only"
SIGNUPS = []

@app.route("/signup", methods=["GET", "POST"])
def signup():
    errors = {}
    if request.method == "POST":
        email = request.form.get("email", "").strip()
        if "@" not in email:
            errors["email"] = "Enter a valid email."
        else:
            SIGNUPS.append(email)
            flash("Thanks for signing up!", "success")
            return redirect(url_for("done"))
    return {"form": "signup", "errors": errors}, 422 if errors else 200
@app.get("/done")
def done():
    return {"messages": get_flashed_messages()}
c = app.test_client()
print(c.post("/signup", data={"email": "nope"}).status_code)          # 422
print(c.post("/signup", data={"email": "a@b.c"}, follow_redirects=True).json)
# {'messages': ['Thanks for signing up!']}

from flask import Blueprint, Flask, url_for

blog = Blueprint("blog", __name__, url_prefix="/blog")

