import pytest
from flask import Flask, session

def create_app(config=None):
    app = Flask(__name__)
    app.config.update(SECRET_KEY="test", **(config or {}))
    @app.post("/login")
    def login():
        session["user"] = "ann"
        return {"ok": True}
    @app.get("/me")
    def me():
        return ({"user": session["user"]}, 200) if "user" in session else ({}, 401)
    return app

@pytest.fixture
def client():
    return create_app({"TESTING": True}).test_client()
def test_me_requires_login(client):
    assert client.get("/me").status_code == 401
def test_login_then_me(client):
    client.post("/login")
    assert client.get("/me").get_json() == {"user": "ann"}
if __name__ == "__main__":
    print(pytest.main(["-q", __file__]))   # 2 passed ... then 0 (ExitCode.OK)

import sqlite3
from flask import Flask, current_app, g

app = Flask(__name__)
app.config["DATABASE"] = ":memory:"

def get_db():
    if "db" not in g:                       # open lazily, once per context
        g.db = sqlite3.connect(current_app.config["DATABASE"])
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop("db", None)
    if db is not None:
        db.close()
@app.get("/")
def index():
    get_db(); get_db()                      # second call reuses the connection
    return {"sum": get_db().execute("select 1 + 1").fetchone()[0]}
print(app.test_client().get("/").json)   # {'sum': 2}
try:
    current_app.name
except RuntimeError as e:
    print(str(e).splitlines()[0])        # Working outside of application context.

import time
from flask import Flask, g, request

app = Flask(__name__)

@app.before_request
def start_timer_and_auth():
    g.start = time.perf_counter()
    if request.path.startswith("/admin") and request.headers.get("X-Token") != "s3cret":
        return {"error": "forbidden"}, 403      # short-circuits: view never runs

@app.after_request
def add_headers(response):
    response.headers["X-Elapsed-ms"] = f"{(time.perf_counter() - g.start) * 1000:.1f}"
    return response                             # must return the response

@app.teardown_request
def log_end(exc):
    print("teardown, error:", exc)
@app.get("/admin/stats")
def stats():
    return {"users": 42}
c = app.test_client()
r = c.get("/admin/stats"); print(r.status_code, "X-Elapsed-ms" in r.headers)   # 403 True
print(c.get("/admin/stats", headers={"X-Token": "s3cret"}).json)            # {'users': 42}

from flask import Flask, request
from flask.views import MethodView

app = Flask(__name__)
ITEMS = {1: {"name": "pen"}}

class ItemCollection(MethodView):
    def get(self):
        return [{"id": i, **v} for i, v in ITEMS.items()]
    def post(self):
        new_id = max(ITEMS, default=0) + 1
        ITEMS[new_id] = {"name": request.get_json()["name"]}
        return {"id": new_id}, 201
class Item(MethodView):
    def get(self, item_id):
        return ITEMS.get(item_id) or ({"error": "not found"}, 404)
    def delete(self, item_id):
        ITEMS.pop(item_id, None)
        return "", 204
app.add_url_rule("/items/", view_func=ItemCollection.as_view("items"))
app.add_url_rule("/items/<int:item_id>", view_func=Item.as_view("item"))
c = app.test_client()
print(c.post("/items/", json={"name": "ink"}).json, c.get("/items/").json)
# {'id': 2} [{'id': 1, 'name': 'pen'}, {'id': 2, 'name': 'ink'}]
print(c.delete("/items/1").status_code, c.put("/items/1").status_code)   # 204 405

from flask import Flask, request
from werkzeug.middleware.proxy_fix import ProxyFix

def create_app():
    app = Flask(__name__)
    app.wsgi_app = ProxyFix(app.wsgi_app, x_for=1, x_proto=1, x_host=1)

    @app.get("/healthz")
    def health():
        return {"status": "ok"}

    @app.get("/whoami")
    def whoami():
        return {"ip": request.remote_addr, "scheme": request.scheme, "host": request.host}

    return app

# Production: gunicorn -w 4 -b 0.0.0.0:8000 "myapp:create_app()"
app = create_app()
r = app.test_client().get("/whoami", headers={
    "X-Forwarded-For": "203.0.113.9", "X-Forwarded-Proto": "https", "X-Forwarded-Host": "example.com"})
print(r.json)   # {'host': 'example.com', 'ip': '203.0.113.9', 'scheme': 'https'}

from flask import Flask

app = Flask(__name__)

@app.get("/hi")
def hi():
    return "hi from flask"

class Timing:                                   # minimal WSGI middleware
    def __init__(self, wsgi_app):
        self.wsgi_app = wsgi_app
    def __call__(self, environ, start_response):
        def sr(status, headers, exc_info=None):
            return start_response(status, headers + [("X-Wrapped", "yes")], exc_info)
        return self.wsgi_app(environ, sr)

app.wsgi_app = Timing(app.wsgi_app)

def start_response(status, headers, exc_info=None):
    print(status, dict(headers)["X-Wrapped"])
environ = {"REQUEST_METHOD": "GET", "PATH_INFO": "/hi", "SERVER_NAME": "x",
           "SERVER_PORT": "80", "wsgi.url_scheme": "http"}
print(b"".join(app(environ, start_response)))   # called like a WSGI server would
# 200 OK yes
# b'hi from flask'

import threading
from flask import Flask, copy_current_request_context, current_app, request

app = Flask(__name__)
results = []

@app.get("/work")
def work():
    real_app = current_app._get_current_object()
    path = request.path                           # pass plain data into threads

    def plain():
        try: request.path
        except RuntimeError: results.append("no request context in thread")
        with real_app.app_context():
            results.append(f"app ok, path {path}")
    @copy_current_request_context
    def copied():
        results.append(f"copied: {request.path}")
    for fn in (plain, copied):
        t = threading.Thread(target=fn); t.start(); t.join()
    return {"proxy_type": type(request).__name__}
print(app.test_client().get("/work").json)   # {'proxy_type': 'LocalProxy'}
print(*results, sep="\n")
# no request context in thread / app ok, path /work / copied: /work
